impl Fixed for ViewFlags {
    const SIZE: usize = 2;
    fn read(r: &mut Reader<'_>, field: &'static str) -> DResult<Self> {
        let at = r.pos();
        let v = r.u16(field)?;
        Self::from_bits(v).ok_or_else(|| r.err_at(at, ErrorKind::BadFlags, field))
    }
    fn write(&self, w: &mut Writer<'_>, _field: &'static str) -> EResult {
        w.u16(self.0);
        Ok(())
    }
}

/// main → shell → sim_extract (52 bytes). The visible rectangle in tiles (no margin, upper bounds exclusive), and the chart rectangle in chunks (upper bounds exclusive; read only with ViewFlags.chart). The held set is `held_chunks` of it (generated in both languages)
#[derive(Clone, Copy, Debug, PartialEq, PartialOrd)]
pub struct ViewRequest {
    pub view_seq: u32,
    pub surface: SurfaceIndex,
    pub flags: ViewFlags,
    pub x0: i32,
    pub y0: i32,
    pub x1: i32,
    pub y1: i32,
    pub zoom: f32,
    /// 0 none; drives the hover projection, sub_id 0
    pub hovered_serial: Serial,
    /// tiles: half the view's width, at most 64 (§15.6)
    pub audio_half_range: f32,
    pub chart_x0: i32,
    pub chart_y0: i32,
    pub chart_x1: i32,
    pub chart_y1: i32,
}

impl ViewRequest {
    /// The encoded size in bytes.
    pub const SIZE: usize = 52;
    pub const OFFSET_VIEW_SEQ: usize = 0;
    pub const OFFSET_SURFACE: usize = 4;
    pub const OFFSET_FLAGS: usize = 6;
    pub const OFFSET_X0: usize = 8;
    pub const OFFSET_Y0: usize = 12;
    pub const OFFSET_X1: usize = 16;
    pub const OFFSET_Y1: usize = 20;
    pub const OFFSET_ZOOM: usize = 24;
    pub const OFFSET_HOVERED_SERIAL: usize = 28;
    pub const OFFSET_AUDIO_HALF_RANGE: usize = 32;
    pub const OFFSET_CHART_X0: usize = 36;
    pub const OFFSET_CHART_Y0: usize = 40;
    pub const OFFSET_CHART_X1: usize = 44;
    pub const OFFSET_CHART_Y1: usize = 48;

    /// Appends the text dump of the fields (test/fixtures/codec), each path prefixed by `prefix`.
    pub fn dump(&self, d: &mut Dump, prefix: &str) {
        d.int(&format!("{prefix}view_seq"), i128::from(self.view_seq));
        d.int(&format!("{prefix}surface"), i128::from(self.surface.0));
        d.int(&format!("{prefix}flags"), i128::from(self.flags.bits()));
        d.int(&format!("{prefix}x0"), i128::from(self.x0));
        d.int(&format!("{prefix}y0"), i128::from(self.y0));
        d.int(&format!("{prefix}x1"), i128::from(self.x1));
        d.int(&format!("{prefix}y1"), i128::from(self.y1));
        d.f32(&format!("{prefix}zoom"), self.zoom);
        d.int(&format!("{prefix}hovered_serial"), i128::from(self.hovered_serial.0));
        d.f32(&format!("{prefix}audio_half_range"), self.audio_half_range);
        d.int(&format!("{prefix}chart_x0"), i128::from(self.chart_x0));
        d.int(&format!("{prefix}chart_y0"), i128::from(self.chart_y0));
        d.int(&format!("{prefix}chart_x1"), i128::from(self.chart_x1));
        d.int(&format!("{prefix}chart_y1"), i128::from(self.chart_y1));
    }
}

impl Default for ViewRequest {
    fn default() -> Self {
        Self {
            view_seq: 0,
            surface: SurfaceIndex::default(),
            flags: ViewFlags::default(),
            x0: 0,
            y0: 0,
            x1: 0,
            y1: 0,
            zoom: 0.0,
            hovered_serial: Serial::default(),
            audio_half_range: 0.0,
            chart_x0: 0,
            chart_y0: 0,
            chart_x1: 0,
            chart_y1: 0,
        }
    }
}

impl Fixed for ViewRequest {
    const SIZE: usize = 52;
    fn read(r: &mut Reader<'_>, _field: &'static str) -> DResult<Self> {
        let f_view_seq = r.u32("ViewRequest.view_seq")?;
        let f_surface = SurfaceIndex::read(r, "ViewRequest.surface")?;
        let f_flags = ViewFlags::read(r, "ViewRequest.flags")?;
        let f_x0 = r.i32("ViewRequest.x0")?;
        let f_y0 = r.i32("ViewRequest.y0")?;
        let f_x1 = r.i32("ViewRequest.x1")?;
        let f_y1 = r.i32("ViewRequest.y1")?;
        let f_zoom = r.f32("ViewRequest.zoom")?;
        let f_hovered_serial = Serial::read(r, "ViewRequest.hovered_serial")?;
        let f_audio_half_range = r.f32("ViewRequest.audio_half_range")?;
        let f_chart_x0 = r.i32("ViewRequest.chart_x0")?;
        let f_chart_y0 = r.i32("ViewRequest.chart_y0")?;
        let f_chart_x1 = r.i32("ViewRequest.chart_x1")?;
        let f_chart_y1 = r.i32("ViewRequest.chart_y1")?;
        Ok(Self {
            view_seq: f_view_seq,
            surface: f_surface,
            flags: f_flags,
            x0: f_x0,
            y0: f_y0,
            x1: f_x1,
            y1: f_y1,
            zoom: f_zoom,
            hovered_serial: f_hovered_serial,
            audio_half_range: f_audio_half_range,
            chart_x0: f_chart_x0,
            chart_y0: f_chart_y0,
            chart_x1: f_chart_x1,
            chart_y1: f_chart_y1,
        })
    }
    fn write(&self, w: &mut Writer<'_>, _field: &'static str) -> EResult {
        w.u32(self.view_seq);
        self.surface.write(w, "ViewRequest.surface")?;
        self.flags.write(w, "ViewRequest.flags")?;
        w.i32(self.x0);
        w.i32(self.y0);
        w.i32(self.x1);
        w.i32(self.y1);
        w.f32(self.zoom, "ViewRequest.zoom")?;
        self.hovered_serial.write(w, "ViewRequest.hovered_serial")?;
        w.f32(self.audio_half_range, "ViewRequest.audio_half_range")?;
        w.i32(self.chart_x0);
        w.i32(self.chart_y0);
        w.i32(self.chart_x1);
        w.i32(self.chart_y1);
        Ok(())
    }
}

/// "PWPK" (§15.4).
pub const PACKET_MAGIC: u32 = 1263556432;
pub const PACKET_HEADER_SIZE: usize = 32;
pub const PACKET_DIRECTORY_ENTRY_SIZE: usize = 16;
/// The shell's packet buffers and their initial size (§15.4).
pub const PACKET_BUFFERS: usize = 3;
pub const PACKET_BUFFER_INITIAL_BYTES: usize = 262144;

impl PacketSection {
    /// How the main thread applies the section (§15.4).
    pub const fn kind(self) -> SectionKind {
        match self {
            Self::ChunkTiles => SectionKind::Delta,
            Self::ChunkEntities => SectionKind::Delta,
            Self::Dyn => SectionKind::Snapshot,
            Self::Hands => SectionKind::Snapshot,
            Self::BeltGeom => SectionKind::Delta,
            Self::BeltItems => SectionKind::Snapshot,
            Self::Movers => SectionKind::Snapshot,
            Self::OverlayChunk => SectionKind::Delta,
            Self::OverlayStaffing => SectionKind::Delta,
            Self::Chart => SectionKind::Delta,
            Self::Events => SectionKind::Event,
            Self::Ui => SectionKind::Delta,
            Self::AudioWorking => SectionKind::Snapshot,
            Self::ChunkObjects => SectionKind::Delta,
            Self::ChunkResources => SectionKind::Delta,
            Self::BeltRetire => SectionKind::Delta,
            Self::ChartPristine => SectionKind::Delta,
        }
    }

    /// The section's record version (the directory's `record_version`).
    pub const fn record_version(self) -> u16 {
        match self {
            Self::ChunkTiles => 1,
            Self::ChunkEntities => 1,
            Self::Dyn => 1,
            Self::Hands => 1,
            Self::BeltGeom => 1,
            Self::BeltItems => 1,
            Self::Movers => 1,
            Self::OverlayChunk => 1,
            Self::OverlayStaffing => 1,
            Self::Chart => 1,
            Self::Events => 1,
            Self::Ui => 1,
            Self::AudioWorking => 1,
            Self::ChunkObjects => 1,
            Self::ChunkResources => 1,
            Self::BeltRetire => 1,
            Self::ChartPristine => 1,
        }
    }

    /// The size of each record of a fixed-record section; None for variable records.
    pub const fn record_size(self) -> Option<usize> {
        match self {
            Self::ChunkTiles => Some(1036),
            Self::ChunkEntities => None,
            Self::Dyn => Some(20),
            Self::Hands => Some(24),
            Self::BeltGeom => None,
            Self::BeltItems => None,
            Self::Movers => Some(32),
            Self::OverlayChunk => Some(12),
            Self::OverlayStaffing => Some(12),
            Self::Chart => Some(4108),
            Self::Events => None,
            Self::Ui => None,
            Self::AudioWorking => Some(16),
            Self::ChunkObjects => None,
            Self::ChunkResources => None,
            Self::BeltRetire => Some(8),
            Self::ChartPristine => Some(8),
        }
    }
}

/// The chunk key of chunk (cx, cy) (§4.4): (cx + 2^15) × 2^16 + (cy + 2^15), for cx and cy in
/// −32,768 … 32,767.
pub const fn chunk_key(cx: i32, cy: i32) -> ChunkKey {
    ChunkKey((((cx + 32768) as u32) << 16) | ((cy + 32768) as u32 & 0xFFFF))
}

/// The chunk of a key.
pub const fn chunk_xy(key: ChunkKey) -> (i32, i32) {
    ((key.0 >> 16) as i32 - 32768, (key.0 & 0xFFFF) as i32 - 32768)
}

/// The chunk holding tile coordinate `t` (32 tiles per chunk, flooring toward −∞).
pub const fn tile_chunk(t: i32) -> i32 {
    t >> 5
}

/// A rectangle of chunks, both corners included.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ChunkRect {
    pub cx0: i32,
    pub cy0: i32,
    pub cx1: i32,
    pub cy1: i32,
}

impl ChunkRect {
    pub const fn contains(&self, cx: i32, cy: i32) -> bool {
        cx >= self.cx0 && cx <= self.cx1 && cy >= self.cy0 && cy <= self.cy1
    }
}

/// The held set (§15.4): the chunks overlapping the view request's visible rectangle (tiles, upper bounds
/// exclusive) grown by one chunk on every side, within the chunk-key range; None when the rectangle is
/// empty. src/shared/gen/packet.ts has the same function.
pub fn held_chunks(v: &ViewRequest) -> Option<ChunkRect> {
    if v.x1 <= v.x0 || v.y1 <= v.y0 {
        return None;
    }
    let lo = |t: i32| (tile_chunk(t) - 1).clamp(-32768, 32767);
    let hi = |t: i32| (tile_chunk(t - 1) + 1).clamp(-32768, 32767);
    Some(ChunkRect { cx0: lo(v.x0), cy0: lo(v.y0), cx1: hi(v.x1), cy1: hi(v.y1) })
}

/// Writes a packet (§15.4): the header (state_gen and view_seq zero, for the shell to fill), a directory of
/// `sections` entries, then each section 8-aligned, in ascending type.
#[derive(Debug)]
pub struct PacketBuilder {
    start: usize,
    declared: usize,
    written: usize,
    last: u16,
    open: Option<(usize, usize)>,
}

impl PacketBuilder {
    /// Writes the header and an empty directory for `sections` sections.
    pub fn begin(w: &mut Writer<'_>, sections: usize, tick: u32, flags: PacketFlags, daylight: u16) -> Self {
        let start = w.pos();
        w.u32(PACKET_MAGIC);
        w.u16(crate::PACKET_VERSION);
        w.u16(flags.bits());
        w.u32(0);
        w.u32(tick);
        w.u32(0);
        w.u16(daylight);
        w.u16(sections as u16);
        w.u32(0);
        w.u32(0);
        w.zeros(sections * PACKET_DIRECTORY_ENTRY_SIZE);
        Self { start, declared: sections, written: 0, last: 0, open: None }
    }

    /// Starts the next section; types must ascend.
    pub fn section(&mut self, w: &mut Writer<'_>, t: PacketSection) -> EResult {
        if self.open.is_some() || self.written == self.declared || t.value() <= self.last {
            return Err(enc_err(ErrorKind::Unsorted, "PacketBuilder.section"));
        }
        w.pad(self.start, 8);
        let entry = self.start + PACKET_HEADER_SIZE + self.written * PACKET_DIRECTORY_ENTRY_SIZE;
        w.patch_u16(entry, t.value());
        w.patch_u16(entry + 2, t.record_version());
        w.patch_u32(entry + 4, (w.pos() - self.start) as u32);
        self.open = Some((entry, w.pos()));
        self.last = t.value();
        Ok(())
    }

    /// Ends the open section with its record count.
    pub fn end(&mut self, w: &mut Writer<'_>, count: u32) -> EResult {
        let Some((entry, at)) = self.open.take() else {
            return Err(enc_err(ErrorKind::Inconsistent, "PacketBuilder.end"));
        };
        w.patch_u32(entry + 8, (w.pos() - at) as u32);
        w.patch_u32(entry + 12, count);
        self.written += 1;
        Ok(())
    }

    /// Checks that every declared section was written and fills in the packet's length.
    pub fn finish(self, w: &mut Writer<'_>) -> EResult {
        if self.open.is_some() || self.written != self.declared {
            return Err(enc_err(ErrorKind::BadCount, "PacketBuilder.finish"));
        }
        w.pad(self.start, 8);
        w.patch_u32(self.start + 24, (w.pos() - self.start) as u32);
        Ok(())
    }
}
